#!/usr/bin/env python3
"""flamelens - an interactive flamegraph viewer for the terminal."""
import os
import sys
import re
import time
import select

VERSION = "0.3.1"


class CliError(Exception):
    def __init__(self, msg, usage=None):
        super().__init__(msg)
        self.msg = msg
        self.usage = usage


def prog_name():
    return os.path.basename(sys.argv[0] or "flamelens")


def usage_line(form="[OPTIONS] [FILENAME]"):
    return f"Usage: {prog_name()} {form}"


def print_help(stream=sys.stdout):
    p = prog_name()
    text = (
        f"Usage: {p} [OPTIONS] [FILENAME]\n"
        "\n"
        "Arguments:\n"
        "  [FILENAME]  Profile data filename\n"
        "\n"
        "Options:\n"
        "      --sorted   Whether to sort the stacks by time spent\n"
        "      --echo     Print data to stdout on exit. Useful when piping to other tools\n"
        "      --debug    Show debug info\n"
        "  -h, --help     Print help\n"
        "  -V, --version  Print version\n"
    )
    stream.write(text)


def print_version(stream=sys.stdout):
    stream.write(f"flamelens {VERSION}\n")


def print_error(msg, usage_form="[OPTIONS] [FILENAME]"):
    sys.stderr.write(f"error: {msg}\n\n")
    sys.stderr.write(f"{usage_line(usage_form)}\n\n")
    sys.stderr.write("For more information, try '--help'.\n")


SIMILAR = {
    "sort": "--sorted",
    "sorted": "--sorted",
    "echo": "--echo",
    "echos": "--echo",
    "debug": "--debug",
    "help": "--help",
    "ver": "--version",
    "version": "--version",
}


def similar_long(name):
    # Simple prefix / close-match suggestion
    base = name.lstrip("-")
    options = ["--sorted", "--echo", "--debug", "--help", "--version"]
    # Exact prefix match
    for o in options:
        if o[2:].startswith(base) and o[2:] != base:
            return o
    # Startswith partial
    for o in options:
        if base.startswith(o[2:3]) and abs(len(o) - 2 - len(base)) <= 2:
            # quick heuristic using Levenshtein-ish: compare first few chars
            if o[2:].startswith(base[:min(len(base), len(o)-2)]):
                return o
    # fallback via table
    return SIMILAR.get(base)


def parse_args(argv):
    args = list(argv[1:])
    filename = None
    sorted_flag = False
    echo_flag = False
    debug_flag = False
    seen_positional = False
    help_flag = False
    version_flag = False
    # We want clap-like behavior
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--":
            i += 1
            # remaining args treated as positionals
            for rest in args[i:]:
                if seen_positional:
                    raise CliError(f"unexpected argument '{rest}' found")
                filename = rest
                seen_positional = True
            break
        if a.startswith("--"):
            # long option
            name_value = a[2:]
            if "=" in name_value:
                name, value = name_value.split("=", 1)
                has_value = True
            else:
                name, value = name_value, None
                has_value = False
            if name == "help":
                if has_value:
                    raise CliError(
                        f"unexpected value '{value}' for '--help' found; no more were expected",
                        "--help [FILENAME]",
                    )
                help_flag = True
            elif name == "version":
                if has_value:
                    raise CliError(
                        f"unexpected value '{value}' for '--version' found; no more were expected",
                        "--version [FILENAME]",
                    )
                version_flag = True
            elif name == "sorted":
                if has_value:
                    raise CliError(
                        f"unexpected value '{value}' for '--sorted' found; no more were expected",
                        "--sorted [FILENAME]",
                    )
                sorted_flag = True
            elif name == "echo":
                if has_value:
                    raise CliError(
                        f"unexpected value '{value}' for '--echo' found; no more were expected",
                        "--echo [FILENAME]",
                    )
                echo_flag = True
            elif name == "debug":
                if has_value:
                    raise CliError(
                        f"unexpected value '{value}' for '--debug' found; no more were expected",
                        "--debug [FILENAME]",
                    )
                debug_flag = True
            else:
                suggest = similar_long(name)
                msg = f"unexpected argument '--{name}' found"
                if suggest:
                    msg += f"\n\n  tip: a similar argument exists: '{suggest}'"
                else:
                    msg += f"\n\n  tip: to pass '--{name}' as a value, use '-- --{name}'"
                raise CliError(msg, "<FILENAME|--sorted|--echo|--debug>" if suggest else "[OPTIONS] [FILENAME]")
            i += 1
            continue
        if a.startswith("-") and len(a) > 1 and a != "-":
            # short option
            rest = a[1:]
            # Only -h and -V supported
            if rest == "h":
                help_flag = True
                i += 1
                continue
            if rest == "V":
                version_flag = True
                i += 1
                continue
            raise CliError(
                f"unexpected argument '{a}' found\n\n  tip: to pass '{a}' as a value, use '-- {a}'"
            )
        # positional
        if seen_positional:
            raise CliError(f"unexpected argument '{a}' found")
        filename = a
        seen_positional = True
        i += 1

    return {
        "filename": filename,
        "sorted": sorted_flag,
        "echo": echo_flag,
        "debug": debug_flag,
        "help": help_flag,
        "version": version_flag,
    }


def parse_folded(data):
    """Parse folded-stacks format. Returns root Frame."""
    root = {"name": "all", "total": 0, "own": 0, "children": {}}
    for line in data.splitlines():
        line = line.strip()
        if not line:
            continue
        # Expect "frame;frame;frame N"
        m = re.match(r"^(.*?)\s+(\d+)\s*$", line)
        if not m:
            continue
        stack_str, count = m.group(1), int(m.group(2))
        frames = stack_str.split(";")
        node = root
        node["total"] += count
        for idx, f in enumerate(frames):
            if f not in node["children"]:
                node["children"][f] = {"name": f, "total": 0, "own": 0, "children": {}}
            node = node["children"][f]
            node["total"] += count
            if idx == len(frames) - 1:
                node["own"] += count
    return root


def tree_leaves_and_levels(root, sorted_flag=False):
    """Flatten the tree into a list of frames with (level, start, width, name, samples, parent_total, ...)."""
    rows = []  # list of list of frames at each level
    def walk(node, level, start, total_root):
        if level >= len(rows):
            rows.append([])
        width = node["total"]
        rows[level].append({
            "name": node["name"],
            "total": node["total"],
            "own": node["own"],
            "start": start,
            "width": width,
        })
        children = list(node["children"].values())
        if sorted_flag:
            children.sort(key=lambda c: -c["total"])
        cur = start
        for c in children:
            walk(c, level + 1, cur, total_root)
            cur += c["total"]
    walk(root, 0, 0, root["total"])
    return rows


def read_input(filename):
    if filename:
        try:
            with open(filename, "rb") as f:
                return f.read().decode("utf-8", errors="replace")
        except OSError as e:
            # Mimic Rust panic output
            pid = os.getpid()
            kind = rust_io_error_kind(e.errno)
            msg = os_error_message(e.errno)
            sys.stderr.write(
                f"\nthread 'main' ({pid}) panicked at src/main.rs:44:47:\n"
                f"Could not read file: Os {{ code: {e.errno}, kind: {kind}, message: \"{msg}\" }}\n"
                f"note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n"
            )
            sys.exit(101)
    else:
        data = sys.stdin.read()
        return data


def rust_io_error_kind(errno):
    import errno as E
    mapping = {
        E.ENOENT: "NotFound",
        E.EACCES: "PermissionDenied",
        E.EEXIST: "AlreadyExists",
        E.EAGAIN: "WouldBlock",
        E.EWOULDBLOCK: "WouldBlock",
        E.EINVAL: "InvalidInput",
        E.EISDIR: "IsADirectory",
        E.ENOTDIR: "NotADirectory",
        E.ENOSPC: "StorageFull",
    }
    return mapping.get(errno, "Uncategorized")


def os_error_message(errno):
    return os.strerror(errno)


def run_tui(data, root, opts):
    """Run the curses TUI. Return on quit."""
    import curses
    # Check tty
    try:
        if not sys.stdout.isatty():
            raise OSError(11, "Resource temporarily unavailable")
        # Use curses
        curses.wrapper(_curses_main, data, root, opts)
    except OSError as e:
        kind = rust_io_error_kind(e.errno)
        msg = os_error_message(e.errno) if e.errno else str(e)
        sys.stderr.write(
            f"\nError: Os {{ code: {e.errno or 0}, kind: {kind}, message: \"{msg}\" }}\n"
        )
        sys.exit(1)


def _curses_main(stdscr, data, root, opts):
    import curses
    curses.curs_set(0)
    stdscr.nodelay(False)
    stdscr.keypad(True)

    view = 0  # 0=flamegraph, 1=top
    selected_level = 0
    selected_idx = 0
    search = ""
    search_mode = False
    match_text = ""
    zoom_root = root
    rows = tree_leaves_and_levels(zoom_root, opts["sorted"])
    sort_mode = "own"  # for top view
    top_offset = 0
    fg_offset = 0

    def redraw():
        stdscr.erase()
        h, w = stdscr.getmaxyx()
        if h < 5 or w < 20:
            stdscr.refresh()
            return
        # Top bar
        hr = "─" * w
        stdscr.addnstr(0, 0, hr, w)
        # Title
        if view == 0:
            title_left = " [Flamegraph] | Top"
        else:
            title_left = " Flamegraph | [Top]"
        title_right = f"flamelens v{VERSION}"
        center = opts.get("filename_display", "")
        stdscr.addnstr(1, 0, title_left, min(len(title_left), w))
        if w > len(title_right) + 2:
            stdscr.addnstr(1, w - len(title_right) - 1, title_right, len(title_right))
        if center and w > len(center) + 40:
            stdscr.addnstr(1, (w - len(center)) // 2, center, len(center))
        stdscr.addnstr(2, 0, hr, w)

        content_top = 3
        content_bottom = h - 5
        total_root = zoom_root["total"] or 1

        if view == 0:
            # Flamegraph
            local_rows = tree_leaves_and_levels(zoom_root, opts["sorted"])
            for level_idx, row in enumerate(local_rows):
                y = content_top + level_idx - fg_offset
                if y < content_top or y >= content_bottom:
                    continue
                for f in row:
                    xs = int(f["start"] * w / total_root)
                    xw = max(1, int(f["width"] * w / total_root))
                    if xs >= w:
                        continue
                    xw = min(xw, w - xs)
                    name = f["name"][: xw - 1] if xw > 1 else ""
                    attr = curses.A_NORMAL
                    if level_idx == selected_level and _contains_idx(local_rows, level_idx, f, selected_idx):
                        attr = curses.A_REVERSE
                    try:
                        stdscr.addnstr(y, xs, (" " + name).ljust(xw)[:xw], xw, attr)
                    except curses.error:
                        pass
            # Selected info
            stdscr.addnstr(h - 4, 0, "Selected " + "─" * max(0, w - 9), w)
            sel = _get_selected(local_rows, selected_level, selected_idx)
            if sel:
                pct = 100.0 * sel["total"] / total_root if total_root else float("nan")
                info = f"{sel['name']} [{sel['total']} samples, {pct:.2f}% of all]"
                stdscr.addnstr(h - 3, 0, info, w)
            stdscr.addnstr(h - 2, 0, hr, w)
            hint = "[hjkl: move cursor] [f/b: scroll] [enter/esc: zoom] [/: search] [#: search like cursor] [r: reset] [tab: switch view] [q: quit]"
            if match_text:
                hint = "[hjkl: move cursor] [f/b: scroll] [enter/esc: zoom] [/: search] [#: search like cursor] [n/N: next/prev search] [r: reset] [tab: switch view] [q: quit]"
            if w > len(hint) + 2:
                stdscr.addnstr(h - 1, (w - len(hint)) // 2, hint, len(hint))
            else:
                stdscr.addnstr(h - 1, 0, hint, w)
        else:
            # Top view
            header = f"{'Total':<14}{'Own'}{(' [▼]' if sort_mode == 'own' else ''):<9} {'Name'}"
            stdscr.addnstr(content_top - 0, 0, header, w)
            # Flatten frames
            frames = []
            def walk(n):
                for c in n["children"].values():
                    frames.append(c)
                    walk(c)
            walk(zoom_root)
            if sort_mode == "own":
                frames.sort(key=lambda f: -f["own"])
            else:
                frames.sort(key=lambda f: -f["total"])
            for idx, f in enumerate(frames):
                y = content_top + 1 + idx - top_offset
                if y < content_top + 1 or y >= content_bottom:
                    continue
                tpct = 100.0 * f["total"] / total_root
                opct = 100.0 * f["own"] / total_root
                line = f"{f['total']} ({tpct:.2f}%)".ljust(14) + f"{f['own']} ({opct:.2f}%)".ljust(14) + f["name"]
                stdscr.addnstr(y, 0, line, w)
            stdscr.addnstr(h - 2, 0, hr, w)
            hint = "[j/k: move cursor] [f/b: scroll] [1: sort by total] [2: sort by own] [/: filter] [r: reset] [tab: switch view] [q: quit]"
            if w > len(hint) + 2:
                stdscr.addnstr(h - 1, (w - len(hint)) // 2, hint, len(hint))
            else:
                stdscr.addnstr(h - 1, 0, hint, w)

        stdscr.refresh()

    while True:
        redraw()
        try:
            ch = stdscr.getch()
        except KeyboardInterrupt:
            return
        if ch in (ord("q"), 3):  # q or Ctrl+C
            return
        if ch == 9:  # Tab
            view = 1 - view
            continue
        if view == 0:
            if ch in (ord("h"),):
                selected_idx = max(0, selected_idx - 1)
            elif ch in (ord("l"),):
                selected_idx += 1
            elif ch in (ord("j"),):
                selected_level += 1
            elif ch in (ord("k"),):
                selected_level = max(0, selected_level - 1)
            elif ch in (ord("f"),):
                fg_offset += 1
            elif ch in (ord("b"),):
                fg_offset = max(0, fg_offset - 1)
            elif ch in (ord("g"),):
                fg_offset = 0
            elif ch in (ord("G"),):
                fg_offset = 10000
            elif ch in (ord("r"),):
                zoom_root = root
                selected_level = 0
                selected_idx = 0
                fg_offset = 0
                match_text = ""
            elif ch == 10:  # Enter
                # zoom
                lr = tree_leaves_and_levels(zoom_root, opts["sorted"])
                sel = _get_selected(lr, selected_level, selected_idx)
                if sel:
                    # find node in tree
                    node = _find_node(zoom_root, sel["name"])
                    if node:
                        zoom_root = node
                        selected_level = 0
                        selected_idx = 0
            elif ch == 27:  # Escape
                zoom_root = root
        else:
            if ch == ord("1"):
                sort_mode = "total"
            elif ch == ord("2"):
                sort_mode = "own"
            elif ch == ord("r"):
                pass


def _contains_idx(rows, level, frame, idx):
    if level < 0 or level >= len(rows):
        return False
    if 0 <= idx < len(rows[level]):
        return rows[level][idx] is frame
    return False


def _get_selected(rows, level, idx):
    if 0 <= level < len(rows) and 0 <= idx < len(rows[level]):
        return rows[level][idx]
    return None


def _find_node(root, name):
    if root["name"] == name:
        return root
    for c in root["children"].values():
        r = _find_node(c, name)
        if r:
            return r
    return None


def main():
    try:
        opts = parse_args(sys.argv)
    except CliError as e:
        print_error(e.msg, e.usage or "[OPTIONS] [FILENAME]")
        sys.exit(2)

    if opts["help"]:
        print_help()
        sys.exit(0)
    if opts["version"]:
        print_version()
        sys.exit(0)

    data = read_input(opts["filename"])
    root = parse_folded(data)
    opts["filename_display"] = opts["filename"] or ""

    try:
        run_tui(data, root, opts)
    finally:
        if opts["echo"]:
            sys.stdout.write(data)
            if data and not data.endswith("\n"):
                sys.stdout.write("\n")


if __name__ == "__main__":
    main()
