#!/usr/bin/env python3
"""flamelens - an interactive flamegraph viewer for the terminal."""
import os
import sys
import re
import time
import select

VERSION = "0.3.1"


class CliError(Exception):
    def __init__(self, msg, usage=None):
        super().__init__(msg)
        self.msg = msg
        self.usage = usage


def prog_name():
    return os.path.basename(sys.argv[0] or "flamelens")


def usage_line(form="[OPTIONS] [FILENAME]"):
    return f"Usage: {prog_name()} {form}"


def print_help(stream=sys.stdout):
    p = prog_name()
    text = (
        f"Usage: {p} [OPTIONS] [FILENAME]\n"
        "\n"
        "Arguments:\n"
        "  [FILENAME]  Profile data filename\n"
        "\n"
        "Options:\n"
        "      --sorted   Whether to sort the stacks by time spent\n"
        "      --echo     Print data to stdout on exit. Useful when piping to other tools\n"
        "      --debug    Show debug info\n"
        "  -h, --help     Print help\n"
        "  -V, --version  Print version\n"
    )
    stream.write(text)


def print_version(stream=sys.stdout):
    stream.write(f"flamelens {VERSION}\n")


def print_error(msg, usage_form="[OPTIONS] [FILENAME]"):
    sys.stderr.write(f"error: {msg}\n\n")
    sys.stderr.write(f"{usage_line(usage_form)}\n\n")
    sys.stderr.write("For more information, try '--help'.\n")


SIMILAR = {
    "sort": "--sorted",
    "sorted": "--sorted",
    "echo": "--echo",
    "echos": "--echo",
    "debug": "--debug",
    "help": "--help",
    "ver": "--version",
    "version": "--version",
}


def similar_long(name):
    # Simple prefix / close-match suggestion
    base = name.lstrip("-")
    options = ["--sorted", "--echo", "--debug", "--help", "--version"]
    # Exact prefix match
    for o in options:
        if o[2:].startswith(base) and o[2:] != base:
            return o
    # Startswith partial
    for o in options:
        if base.startswith(o[2:3]) and abs(len(o) - 2 - len(base)) <= 2:
            # quick heuristic using Levenshtein-ish: compare first few chars
            if o[2:].startswith(base[:min(len(base), len(o)-2)]):
                return o
    # fallback via table
    return SIMILAR.get(base)


def parse_args(argv):
    args = list(argv[1:])
    filename = None
    sorted_flag = False
    echo_flag = False
    debug_flag = False
    seen_positional = False
    help_flag = False
    version_flag = False
    # We want clap-like behavior
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--":
            i += 1
            # remaining args treated as positionals
            for rest in args[i:]:
                if seen_positional:
                    raise CliError(f"unexpected argument '{rest}' found")
                filename = rest
                seen_positional = True
            break
        if a.startswith("--"):
            # long option
            name_value = a[2:]
            if "=" in name_value:
                name, value = name_value.split("=", 1)
                has_value = True
            else:
                name, value = name_value, None
                has_value = False
            if name == "help":
                if has_value:
                    raise CliError(
                        f"unexpected value '{value}' for '--help' found; no more were expected",
                        "--help [FILENAME]",
                    )
                help_flag = True
            elif name == "version":
                if has_value:
                    raise CliError(
                        f"unexpected value '{value}' for '--version' found; no more were expected",
                        "--version [FILENAME]",
                    )
                version_flag = True
            elif name == "sorted":
                if has_value:
                    raise CliError(
                        f"unexpected value '{value}' for '--sorted' found; no more were expected",
                        "--sorted [FILENAME]",
                    )
                sorted_flag = True
            elif name == "echo":
                if has_value:
                    raise CliError(
                        f"unexpected value '{value}' for '--echo' found; no more were expected",
                        "--echo [FILENAME]",
                    )
                echo_flag = True
            elif name == "debug":
                if has_value:
                    raise CliError(
                        f"unexpected value '{value}' for '--debug' found; no more were expected",
                        "--debug [FILENAME]",
                    )
                debug_flag = True
            else:
                suggest = similar_long(name)
                msg = f"unexpected argument '--{name}' found"
                if suggest:
                    msg += f"\n\n  tip: a similar argument exists: '{suggest}'"
                else:
                    msg += f"\n\n  tip: to pass '--{name}' as a value, use '-- --{name}'"
                raise CliError(msg, "<FILENAME|--sorted|--echo|--debug>" if suggest else "[OPTIONS] [FILENAME]")
            i += 1
            continue
        if a.startswith("-") and len(a) > 1 and a != "-":
            # short option
            rest = a[1:]
            # Only -h and -V supported
            if rest == "h":
                help_flag = True
                i += 1
                continue
            if rest == "V":
                version_flag = True
                i += 1
                continue
            raise CliError(
                f"unexpected argument '{a}' found\n\n  tip: to pass '{a}' as a value, use '-- {a}'"
            )
        # positional
        if seen_positional:
            raise CliError(f"unexpected argument '{a}' found")
        filename = a
        seen_positional = True
        i += 1

    return {
        "filename": filename,
        "sorted": sorted_flag,
        "echo": echo_flag,
        "debug": debug_flag,
        "help": help_flag,
        "version": version_flag,
    }


def parse_folded(data):
    """Parse folded-stacks format. Returns root Frame."""
    root = {"name": "all", "total": 0, "own": 0, "children": {}}
    for line in data.splitlines():
        line = line.strip()
        if not line:
            continue
        # Expect "frame;frame;frame N"
        m = re.match(r"^(.*?)\s+(\d+)\s*$", line)
        if not m:
            continue
        stack_str, count = m.group(1), int(m.group(2))
        frames = stack_str.split(";")
        node = root
        node["total"] += count
        for idx, f in enumerate(frames):
            if f not in node["children"]:
                node["children"][f] = {"name": f, "total": 0, "own": 0, "children": {}}
            node = node["children"][f]
            node["total"] += count
            if idx == len(frames) - 1:
                node["own"] += count
    return root


def tree_leaves_and_levels(root, sorted_flag=False):
    """Flatten the tree into a list of frames with (level, start, width, name, samples, parent_total, ...)."""
    rows = []  # list of list of frames at each level
    def walk(node, level, start, total_root):
        if level >= len(rows):
            rows.append([])
        width = node["total"]
        rows[level].append({
            "name": node["name"],
            "total": node["total"],
            "own": node["own"],
            "start": start,
            "width": width,
        })
        children = list(node["children"].values())
        if sorted_flag:
            children.sort(key=lambda c: -c["total"])
        cur = start
        for c in children:
            walk(c, level + 1, cur, total_root)
            cur += c["total"]
    walk(root, 0, 0, root["total"])
    return rows


def read_input(filename):
    if filename:
        try:
            with open(filename, "rb") as f:
                return f.read().decode("utf-8", errors="replace")
        except OSError as e:
            # Mimic Rust panic output
            pid = os.getpid()
            kind = rust_io_error_kind(e.errno)
            msg = os_error_message(e.errno)
            sys.stderr.write(
                f"\nthread 'main' ({pid}) panicked at src/main.rs:44:47:\n"
                f"Could not read file: Os {{ code: {e.errno}, kind: {kind}, message: \"{msg}\" }}\n"
                f"note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n"
            )
            sys.exit(101)
    else:
        data = sys.stdin.read()
        return data


def rust_io_error_kind(errno):
    import errno as E
    mapping = {
        E.ENOENT: "NotFound",
        E.EACCES: "PermissionDenied",
        E.EEXIST: "AlreadyExists",
        E.EAGAIN: "WouldBlock",
        E.EWOULDBLOCK: "WouldBlock",
        E.EINVAL: "InvalidInput",
        E.EISDIR: "IsADirectory",
        E.ENOTDIR: "NotADirectory",
        E.ENOSPC: "StorageFull",
    }
    return mapping.get(errno, "Uncategorized")


def os_error_message(errno):
    return os.strerror(errno)


def run_tui(data, root, opts):
    """Run the curses TUI. Return on quit."""
    import curses
    # Check tty
    try:
        if not sys.stdout.isatty():
            raise OSError(11, "Resource temporarily unavailable")
        # Use curses
        curses.wrapper(_curses_main, data, root, opts)
    except OSError as e:
        kind = rust_io_error_kind(e.errno)
        msg = os_error_message(e.errno) if e.errno else str(e)
        sys.stderr.write(
            f"\nError: Os {{ code: {e.errno or 0}, kind: {kind}, message: \"{msg}\" }}\n"
